PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE locations (
  id   INTEGER PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL
);
CREATE TABLE tags (
  id       INTEGER PRIMARY KEY,
  slug     TEXT NOT NULL UNIQUE,
  label    TEXT NOT NULL,
  category TEXT NOT NULL CHECK(category IN ('vibe','dietary','other'))
);
CREATE TABLE restaurants (
  id            INTEGER PRIMARY KEY,
  slug          TEXT NOT NULL UNIQUE,
  name          TEXT NOT NULL,
  cuisine       TEXT,
  location_id   INTEGER REFERENCES locations(id),
  address       TEXT,
  price_tier    INTEGER CHECK(price_tier BETWEEN 1 AND 5),
  website_url   TEXT,
  menu_url      TEXT,
  wishlist_note TEXT,
  created_at    INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at    INTEGER NOT NULL DEFAULT (unixepoch())
, place_id TEXT, lat      REAL, lng      REAL, maps_url TEXT, hero_photo_name TEXT, card_quote TEXT);
CREATE TABLE restaurant_tags (
  restaurant_id INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
  tag_id        INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
  PRIMARY KEY (restaurant_id, tag_id)
);
CREATE TABLE standout_items (
  id           INTEGER PRIMARY KEY,
  review_id    INTEGER NOT NULL REFERENCES reviews(id) ON DELETE CASCADE,
  name         TEXT NOT NULL,
  note         TEXT,
  is_standout  INTEGER NOT NULL DEFAULT 0,
  sort_order   INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE photos (
  id         INTEGER PRIMARY KEY,
  review_id  INTEGER NOT NULL REFERENCES reviews(id) ON DELETE CASCADE,
  r2_key     TEXT NOT NULL,
  alt        TEXT,
  width      INTEGER,
  height     INTEGER,
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_cover   INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE cuisine_suggestions (
  name TEXT PRIMARY KEY
);
CREATE TABLE IF NOT EXISTS "reviews" (
  id              INTEGER PRIMARY KEY,
  restaurant_id   INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
  slug            TEXT NOT NULL UNIQUE,
  visit_date      TEXT,
  meal_type       TEXT,
  rating_overall  REAL NOT NULL,
  rating_food     REAL,
  rating_vibe     REAL,
  rating_service  REAL,
  rating_value    REAL,
  rating_size     REAL,
  commentary      TEXT,
  would_return    INTEGER NOT NULL,
  instagram_url   TEXT,
  status          TEXT NOT NULL DEFAULT 'published'
                    CHECK(status IN ('draft','published')),
  created_at      INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at      INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE posts (
  id                       INTEGER PRIMARY KEY,
  slug                     TEXT NOT NULL UNIQUE,
  kind                     TEXT NOT NULL,            
  source_filter            TEXT NOT NULL,            
  title                    TEXT NOT NULL,
  description              TEXT NOT NULL,            
  body_md                  TEXT NOT NULL,            
  og_image_restaurant_id   INTEGER REFERENCES restaurants(id) ON DELETE SET NULL,
  featured_restaurants_json TEXT NOT NULL DEFAULT '[]',  
  generated_at             INTEGER NOT NULL DEFAULT (unixepoch()),
  published_at             INTEGER,                  
  model                    TEXT,                     
  status                   TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published'))
);
CREATE TABLE topics (
  id              INTEGER PRIMARY KEY,
  query           TEXT NOT NULL UNIQUE,             
  type            TEXT NOT NULL,                    
  filter_value    TEXT NOT NULL,                    
  monthly_volume  INTEGER,                          
  intent          TEXT,                             
  coverage_count  INTEGER NOT NULL DEFAULT 0,       
  paa_json        TEXT,                             
  status          TEXT NOT NULL DEFAULT 'queued'    
                    CHECK (status IN ('queued', 'generating', 'generated', 'skipped')),
  source          TEXT,                             
  notes           TEXT,                             
  post_slug       TEXT,                             
  discovered_at   INTEGER NOT NULL DEFAULT (unixepoch()),
  generated_at    INTEGER,                          
  refreshed_at    INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE related_posts (
  post_slug      TEXT NOT NULL,
  related_slug   TEXT NOT NULL,
  relation_type  TEXT NOT NULL,    
  weight         REAL NOT NULL DEFAULT 1.0,    
  created_at     INTEGER NOT NULL DEFAULT (unixepoch()),
  PRIMARY KEY (post_slug, related_slug)
);
CREATE TABLE restaurant_cuisines (
  restaurant_id INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
  cuisine       TEXT NOT NULL,
  sort_order    INTEGER NOT NULL DEFAULT 0,  
  PRIMARY KEY (restaurant_id, cuisine)
);
CREATE TABLE restaurant_meal_types (
  restaurant_id INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
  meal_type     TEXT NOT NULL,
  PRIMARY KEY (restaurant_id, meal_type)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_photos_review       ON photos(review_id);
CREATE INDEX idx_standout_review     ON standout_items(review_id);
CREATE INDEX idx_restaurant_location ON restaurants(location_id);
CREATE INDEX idx_restaurant_place_id ON restaurants(place_id);
CREATE INDEX idx_reviews_restaurant  ON reviews(restaurant_id);
CREATE INDEX idx_reviews_status_date ON reviews(status, visit_date DESC);
CREATE INDEX idx_reviews_meal        ON reviews(meal_type);
CREATE UNIQUE INDEX idx_posts_kind_source ON posts(kind, source_filter);
CREATE INDEX idx_posts_published ON posts(status, published_at);
CREATE INDEX idx_topics_status_volume
  ON topics(status, monthly_volume DESC, coverage_count DESC);
CREATE INDEX idx_topics_type ON topics(type);
CREATE INDEX idx_related_post   ON related_posts(post_slug, weight DESC);
CREATE INDEX idx_restaurant_cuisines_cuisine
  ON restaurant_cuisines(cuisine COLLATE NOCASE);
CREATE INDEX idx_restaurant_cuisines_restaurant
  ON restaurant_cuisines(restaurant_id);
CREATE INDEX idx_restaurant_meal_types_meal
  ON restaurant_meal_types(meal_type);
CREATE INDEX idx_restaurant_meal_types_restaurant
  ON restaurant_meal_types(restaurant_id);
